// scripts/apply-url-canonical-map.js
// Prebuild step. Rewrites lib/data/valid-urls.json so the sitemap advertises
// only the URL a request actually lands on, using the table generated by
// scripts/build-url-canonical-map.mts.
//
// Measured 2026-08-29, before this step ran: 439 of 3,328 sitemap URLs answered
// 301/308 rather than 200. 195 were /universities/{uni}/{prog}/{spec} alias
// slugs, 244 were /programs/{prog}/{spec} slugs that redirect to a canonical
// spec or to the programme hub. A sitemap full of redirect sources burns crawl
// budget and splits signals across two URLs for the same page.
//
// Nothing is hidden by this pass. A URL is either kept, or replaced by the
// target it already redirects to, and that target is asserted present in the
// output. The original URL keeps working, it just stops being advertised.
//
// Plain CommonJS because the prebuild chain is deliberately tsx-free. See the
// loader-race note in build-programme-allowlist.js. The resolver logic lives in
// the tsx generator; this file only applies its output.
//
// Prebuild chain order: MUST run after prune-noindex-hub-urls.js, which is the
// last step that adds or removes URLs.
//
// Usage:
//   default : rewrite valid-urls.json in place
//   --check : exit 1 if the file still lists a redirect source

const fs = require('fs')
const path = require('path')

const ROOT = path.join(__dirname, '..')
const VALID_URLS = path.join(ROOT, 'lib', 'data', 'valid-urls.json')
const MAP_FILE = path.join(ROOT, 'lib', 'data', 'url-canonical-map.json')
const CHECK = process.argv.includes('--check')

const PROGRAMMES = new Set(['mba', 'mca', 'bba', 'bca', 'bcom', 'mcom', 'ba', 'ma', 'msc', 'bsc'])

const map = JSON.parse(fs.readFileSync(MAP_FILE, 'utf8'))
const before = JSON.parse(fs.readFileSync(VALID_URLS, 'utf8'))

const missing = []
const rewritten = []
const dropped = []
const after = []
const seen = new Set()

for (const url of before) {
  const seg = url.split('/')
  let target = url

  if (seg.length === 5 && seg[1] === 'universities' && PROGRAMMES.has(seg[3])) {
    const key = `${seg[2]}|${seg[3]}|${seg[4]}`
    if (!(key in map.u)) { missing.push(url); continue }
    const canonical = map.u[key]
    target = canonical === null ? null : `/universities/${seg[2]}/${seg[3]}/${canonical}`
  } else if (seg.length === 4 && seg[1] === 'programs' && PROGRAMMES.has(seg[2])) {
    const key = `${seg[2]}|${seg[3]}`
    if (!(key in map.p)) { missing.push(url); continue }
    const canonical = map.p[key]
    target = canonical === '' ? `/programs/${seg[2]}` : `/programs/${seg[2]}/${canonical}`
  }

  if (target === null) { dropped.push(url); continue }
  if (target !== url) rewritten.push([url, target])
  if (!seen.has(target)) { seen.add(target); after.push(target) }
}

// A URL the table does not cover means lib/data.ts or programs-manifest.json
// moved without regenerating the map. Fail the build rather than ship a
// sitemap whose canonical status is unknown.
if (missing.length > 0) {
  console.error(`FAIL: ${missing.length} sitemap URL(s) are absent from ${path.relative(ROOT, MAP_FILE)}.`)
  for (const m of missing.slice(0, 15)) console.error(`    - ${m}`)
  if (missing.length > 15) console.error(`    ...and ${missing.length - 15} more`)
  console.error('')
  console.error('Fix: npx tsx scripts/build-url-canonical-map.mts and stage the diff.')
  process.exit(1)
}

for (const [, target] of rewritten) {
  if (!seen.has(target)) {
    console.error(`FAIL: canonical target missing from output: ${target}`)
    process.exit(1)
  }
}

const changed = rewritten.length + dropped.length

if (CHECK) {
  if (changed === 0) {
    console.log(`OK. valid-urls.json (${before.length} URLs) lists no redirect sources.`)
    process.exit(0)
  }
  console.error(`FAIL: valid-urls.json lists ${changed} URL(s) that redirect or do not resolve.`)
  for (const [from, to] of rewritten.slice(0, 15)) console.error(`    ${from}\n      -> ${to}`)
  for (const d of dropped.slice(0, 10)) console.error(`    ${d}\n      -> does not resolve`)
  console.error('')
  console.error('Fix: node scripts/apply-url-canonical-map.js and stage the diff.')
  process.exit(1)
}

fs.writeFileSync(VALID_URLS, JSON.stringify(after, null, 2) + '\n', 'utf8')
console.log(`Canonicalised valid-urls.json (${before.length} -> ${after.length}).`)
console.log(`  rewritten to canonical : ${rewritten.length}`)
console.log(`  dropped (unresolvable) : ${dropped.length}`)
console.log(`  collapsed as duplicate : ${before.length - dropped.length - after.length}`)
